//! The glue of the `system` component (49) for the module that hosts it, generated by `tools/gen_vtables.py` from `modules/mod_system/API.md`; do not edit.
//!
//! [`Api`] is what the module implements. [`dispatch`] serves a request (a method number and the fields map: the runtime has parsed the
//! envelope) and [`table`] is the module's vtable for other modules, whose functions enter the allocator context of the module (`Ctx`).
#![allow(clippy::all, dead_code)]
use core::ffi::{c_int, c_void};
use xip_abi::cbor::Writer;
use xip_abi::fields as f;
use xip_abi::{System, CallView, Hw, Host, ERR_ARG, ERR_SIZE, ERR_UNSUPPORTED, SystemHeapDump, SystemHeapInfo};

pub const COMPONENT: i32 = 49;
pub const M_HEAP: i32 = 1;
pub const M_HEAP_DUMP: i32 = 2;
pub const M_DUMP_TASKS: i32 = 3;

/// What the module implements. Every method returns `Err(code)` with a negative `ERR_*`.
pub trait Api {
    /// 1. Free, minimum-free and largest-block values, in bytes.
    fn heap(&mut self, hw: &Hw, response: &mut SystemHeapInfo) -> Result<(), i32>;
    /// 2. Kinds: 0 memory regions, 1 block snapshot, 3 trace start, 4 trace dump, 5 trace stop, 6 CBOR block records over native PPP.
    fn heap_dump(&mut self, hw: &Hw, request: &SystemHeapDump) -> Result<(), i32>;
    /// 3. Clients debugging scheduling or memory usage request task names, priorities and remaining stack bytes.
    fn dump_tasks(&mut self, hw: &Hw) -> Result<(), i32>;
}

fn decode_heapdump(fields: &[u8], r: &mut SystemHeapDump) -> Result<(), i32> {
    if let Some(v) = f::get_int(fields, 1)? { r.kind = i32::try_from(v).map_err(|_| ERR_ARG)?; }
    Ok(())
}

fn encode_heapinfo(r: &SystemHeapInfo, out: &mut [u8]) -> Result<usize, i32> {
    let mut w = Writer::new(out);
    w.map(6);
    w.uint(1).uint(r.free as u64);
    w.uint(2).uint(r.largest as u64);
    w.uint(3).uint(r.min_free as u64);
    w.uint(4).uint(r.total as u64);
    w.uint(5).uint(r.internal_free as u64);
    w.uint(6).uint(r.internal_largest as u64);
    w.finish().map(|b| b.len()).ok_or(ERR_SIZE)
}

/// Serve method `method` with the request `fields`; the response map goes to `out`. Returns its length. An unknown method is `ERR_UNSUPPORTED`.
pub fn dispatch<T: Api>(t: &mut T, hw: &Hw, method: i32, fields: &[u8], out: &mut [u8]) -> Result<usize, i32> {
    match method {
        M_HEAP => {
            let mut response = SystemHeapInfo::default();
            t.heap(hw, &mut response)?;
            encode_heapinfo(&response, out)
        }
        M_HEAP_DUMP => {
            let mut request = SystemHeapDump::default();
            decode_heapdump(fields, &mut request)?;
            t.heap_dump(hw, &request)?;
            let mut w = Writer::new(out);
            w.map(0);
            w.finish().map(|b| b.len()).ok_or(ERR_SIZE)
        }
        M_DUMP_TASKS => {
            t.dump_tasks(hw)?;
            let mut w = Writer::new(out);
            w.map(0);
            w.finish().map(|b| b.len()).ok_or(ERR_SIZE)
        }
        _ => Err(ERR_UNSUPPORTED),
    }
}

/// The first argument of every function of the module's table: the host table and the module's state, both valid while the module runs.
#[repr(C)]
pub struct Ctx {
    pub host: *const Host,
    pub state: *mut u8,
}

/// Run `body` in the allocator context of the module (the runtime's thunk has taken the module's lock).
unsafe fn within<T: Api>(ctx: *mut c_void, body: impl FnOnce(&mut T, &Hw) -> Result<(), i32>) -> c_int {
    let ctx = &*(ctx as *const Ctx);
    let Some(hw) = Hw::new(ctx.host) else { return ERR_ARG };
    let saved = xip_abi::heap::enter(ctx.host);
    let rc = match body(&mut *(ctx.state as *mut T), &hw) { Ok(()) => 0, Err(rc) => rc };
    xip_abi::heap::leave(saved);
    rc
}

unsafe extern "C" fn v_heap<T: Api>(ctx: *mut c_void, response: *mut SystemHeapInfo) -> c_int {
    if response.is_null() { return ERR_ARG; }
    within::<T>(ctx, |t, hw| t.heap(hw, &mut *response))
}
unsafe extern "C" fn v_heap_dump<T: Api>(ctx: *mut c_void, request: *const SystemHeapDump) -> c_int {
    if request.is_null() { return ERR_ARG; }
    within::<T>(ctx, |t, hw| t.heap_dump(hw, &*request))
}
unsafe extern "C" fn v_dump_tasks<T: Api>(ctx: *mut c_void) -> c_int {
    within::<T>(ctx, |t, hw| t.dump_tasks(hw))
}

/// The module's table of the `system` component and the context its functions take: a part of the module's state block. The table is built
/// when the module answers `HOST_TABLE`, not as a constant: the function addresses of a position-independent image (ESP32-C6) exist only at run time.
#[repr(C)]
pub struct Hosted {
    pub ctx: Ctx,
    pub table: System,
}
impl Default for Hosted {
    /// All zero: no table yet (the state block of a module starts zeroed).
    fn default() -> Self {
        unsafe { core::mem::zeroed() }
    }
}

/// Answer `HOST_TABLE` for this component with the module's table, whose functions call `T` in the module's allocator context, and the context
/// they take. `hosted` points into the module's state block (it must stay valid while the module runs) and `state` is that block as `T`.
pub fn provide<T: Api>(hw: &Hw, call: &CallView, hosted: *mut Hosted, state: *mut T) -> i32 {
    unsafe {
        (*hosted).ctx = Ctx { host: hw.as_ptr(), state: state.cast() };
        (*hosted).table = System {
            version: 1,
            size: core::mem::size_of::<System>() as u32,
            heap: Some(v_heap::<T>),
            heap_dump: Some(v_heap_dump::<T>),
            dump_tasks: Some(v_dump_tasks::<T>),
        };
        hw.provide_table(call, core::ptr::addr_of!((*hosted).table).cast(), core::ptr::addr_of_mut!((*hosted).ctx).cast(), xip_abi::schema::SCHEMA_SYSTEM)
    }
}
